(405567, 35618, 6504, '<td valign="top">WoW!!!  What a great shot!</td>', 'WoW!!!  What a great shot!', '2003-09-01 01:09:28.000000', NULL, 1),
(405581, 35784, 6504, '<td valign="top">This very well could be the winner</td>', 'This very well could be the winner', '2003-09-01 01:13:28.000000', NULL, 1),
(405587, 35507, 772, '<td valign="top">this is a beautiful photo, but your choice of underexposure doens''t seem to work well for me... I would definitely believe that this would be a much stronger photo (IMO) with a stronger tonal variation.</td>', 'this is a beautiful photo, but your choice of underexposure doens''t seem to work well for me... I would definitely believe that this would be a much stronger photo (IMO) with a stronger tonal variation.', '2003-09-01 01:14:58.000000', NULL, 1),
