(405662, 35661, 6504, '<td valign="top">Beautiful!  The coloring is perfect for this picture, and the angle is very good.</td>', 'Beautiful!  The coloring is perfect for this picture, and the angle is very good.', '2003-09-01 01:29:30.000000', NULL, 1),
(405665, 35463, 11324, '<td valign="top">Actually, I''ve asked a few people about their opinions and we have all concurred that time NEVER repeats itself.  If it is September 26th, 2003 at 9:51 and 12 seconds, that time frame never repeats iself.  People may write you comments like "oh, you can take any picture, give it a catchy title, and it will it any challenge."  I''ll just say that to the educated and intellectual photographer, this is almost an insult.  I was ALMOST fooled by the title, almost gave it a 7 or 8 because I myself have been stumped by a challenge and turned just any ol'' picture into one for the challenge, but then I realized the tile was actually not even true.  Sorry buddy!</td>', 'Actually, I''ve asked a few people about their opinions and we have all concurred that time NEVER repeats itself.  If it is September 26th, 2003 at 9:51 and 12 seconds, that time frame never repeats iself.  People may write you comments like "oh, you can take any picture, give it a catchy title, and it will it any challenge."  I''ll just say that to the educated and intellectual photographer, this is almost an insult.  I was ALMOST fooled by the title, almost gave it a 7 or 8 because I myself have been stumped by a challenge and turned just any ol'' picture into one for the challenge, but then I realized the tile was actually not even true.  Sorry buddy!', '2003-09-01 01:29:56.000000', NULL, 1),
(405668, 35943, 6504, '<td valign="top">Good.   very good, and as a mother of three sons, I get it!</td>', 'Good.   very good, and as a mother of three sons, I get it!', '2003-09-01 01:30:17.000000', NULL, 1),
(405671, 35687, 11034, '<td valign="top">Nice comp. and colours.</td>', 'Nice comp. and colours.', '2003-09-01 01:30:46.000000', NULL, 1),
(405675, 35356, 11324, '<td valign="top">i''d give it a higher rating, but those black garbage cans bother me.  It would have been GREAT without it.  Could we have moved them for the shot?  7</td>', 'i''d give it a higher rating, but those black garbage cans bother me.  It would have been GREAT without it.  Could we have moved them for the shot?  7', '2003-09-01 01:32:04.000000', NULL, 1),
