(405771, 35772, 6504, '<td valign="top">Nice Shot.  Perfect having the planes in the bottom left corner.  Very good.</td>', 'Nice Shot.  Perfect having the planes in the bottom left corner.  Very good.', '2003-09-01 02:01:05.000000', NULL, 1),
(405773, 35892, 6504, '<td valign="top">A little too blurry.</td>', 'A little too blurry.', '2003-09-01 02:01:26.000000', NULL, 1),
