(406215, 34989, 5112, '<td valign="top">I like this picture!  I like it that you left the top sky part, I think it makes the picture more interesting.  Good choice for the challenge.</td>', 'I like this picture!  I like it that you left the top sky part, I think it makes the picture more interesting.  Good choice for the challenge.', '2003-09-01 12:55:17.000000', NULL, 1),
(406218, 35178, 5112, '<td valign="top">Beautiful picture, very good choice for the challenge.  Love the sepia tones.</td>', 'Beautiful picture, very good choice for the challenge.  Love the sepia tones.', '2003-09-01 12:55:52.000000', NULL, 1),
(406222, 35776, 5112, '<td valign="top">You should have waited for this week''s challenge :)  Good picture, even though it''s kind of gross to see so many of them together.</td>', 'You should have waited for this week''s challenge :)  Good picture, even though it''s kind of gross to see so many of them together.', '2003-09-01 12:57:42.000000', NULL, 1),
(406227, 35763, 5112, '<td valign="top">Taken in Ottawa?  Nice shot!</td>', 'Taken in Ottawa?  Nice shot!', '2003-09-01 12:59:26.000000', NULL, 1),
(406233, 35352, 5112, '<td valign="top">What a good idea!</td>', 'What a good idea!', '2003-09-01 13:01:47.000000', NULL, 1),
