(406236, 35911, 5112, '<td valign="top">The colours are beautiful!</td>', 'The colours are beautiful!', '2003-09-01 13:02:51.000000', NULL, 1),
(406239, 35761, 10643, '<td valign="top">as a huge Lego fan I have to love this (even though it looks like it''s not Lego brand bricks, I''ll let that go)! great crop, great colors!</td>', 'as a huge Lego fan I have to love this (even though it looks like it''s not Lego brand bricks, I''ll let that go)! great crop, great colors!', '2003-09-01 13:03:55.000000', NULL, 1),
