INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(406280, 35776, 7304, '<td valign="top">Would have been better in the insect challenge but tough luck. Nice detail. Great color and light.</td>', 'Would have been better in the insect challenge but tough luck. Nice detail. Great color and light.', '2003-09-01 13:30:28.000000', NULL, 1),
(406313, 35926, 10883, '<td valign="top">I like the perspective you chose to take of the building!  The blue sky is also a bonus!</td>', 'I like the perspective you chose to take of the building!  The blue sky is also a bonus!', '2003-09-01 13:52:16.000000', NULL, 1),
(406314, 35885, 10768, '<td valign="top">Love the perspective on this photo.  Nice interpretation of theme.  Good work.</td>', 'Love the perspective on this photo.  Nice interpretation of theme.  Good work.', '2003-09-01 13:52:36.000000', NULL, 1),
(406317, 35851, 10883, '<td valign="top">Nice pic!  It would have been a wee bit cooler if the horses would have had both left legs on the ground and both right legs up.</td>', 'Nice pic!  It would have been a wee bit cooler if the horses would have had both left legs on the ground and both right legs up.', '2003-09-01 13:53:36.000000', NULL, 1),
(406320, 35899, 10883, '<td valign="top">Interesting subject and a nice crop (haha!)</td>', 'Interesting subject and a nice crop (haha!)', '2003-09-01 13:54:56.000000', NULL, 1),
(406330, 35530, 10883, '<td valign="top">The top half of the picture is overexposed and there is quite a bit of detail lost there..</td>', 'The top half of the picture is overexposed and there is quite a bit of detail lost there..', '2003-09-01 13:58:27.000000', NULL, 1),
(406348, 35304, 10883, '<td valign="top">I like this picture!  It would be interesting to see how it would come out if the tower was off centered. - 7</td>', 'I like this picture!  It would be interesting to see how it would come out if the tower was off centered. - 7', '2003-09-01 14:07:24.000000', NULL, 1),
(406366, 35530, 10263, '<td valign="top">I like this photo. It fits the challenge well, has good color and holds my interest. I like the shapes of the shadows and the color that shows in them. Good job :)</td>', 'I like this photo. It fits the challenge well, has good color and holds my interest. I like the shapes of the shadows and the color that shows in them. Good job :)', '2003-09-01 14:16:40.000000', NULL, 1),
(406374, 35696, 10263, '<td valign="top">This photo is striking. I love the patterns and how the object stands out against the sky. Excellent DoF.</td>', 'This photo is striking. I love the patterns and how the object stands out against the sky. Excellent DoF.', '2003-09-01 14:23:18.000000', NULL, 1),
(406380, 35905, 10263, '<td valign="top">I love the expression in the childs eyes here. The white shirts were probably the only things you all had alike, but I would really like to see some color in the clothing. I like the concept :) The opening in the background above the older man''s head is distracting as well as the upper right area that is wrinkled. Nice genes :)</td>', 'I love the expression in the childs eyes here. The white shirts were probably the only things you all had alike, but I would really like to see some color in the clothing. I like the concept :) The opening in the background above the older man''s head is distracting as well as the upper right area that is wrinkled. Nice genes :)', '2003-09-01 14:29:47.000000', NULL, 1),
(406385, 35345, 10263, '<td valign="top">hmmm is this legal in the challenge rules?</td>', 'hmmm is this legal in the challenge rules?', '2003-09-01 14:31:00.000000', NULL, 1),
(406387, 35885, 10263, '<td valign="top">Nice lines in the cars and the buildings. Definately fits the challenge.</td>', 'Nice lines in the cars and the buildings. Definately fits the challenge.', '2003-09-01 14:33:39.000000', NULL, 1),
(406390, 35942, 10263, '<td valign="top">Interesting concept. The specks in the foreground are distracting and I think there is too much foreground. I think a closer crop would have worked better.</td>', 'Interesting concept. The specks in the foreground are distracting and I think there is too much foreground. I think a closer crop would have worked better.', '2003-09-01 14:35:24.000000', NULL, 1),
(406422, 35772, 10883, '<td valign="top">Very cool picture!  Nothing more that can be said about it!  - 9</td>', 'Very cool picture!  Nothing more that can be said about it!  - 9', '2003-09-01 15:32:31.000000', NULL, 1),
(406439, 35919, 7350, '<td valign="top">This is my pick for the winner.  Great shot, great detail.  10.</td>', 'This is my pick for the winner.  Great shot, great detail.  10.', '2003-09-01 15:54:31.000000', NULL, 1),
(406467, 35388, 9576, '<td valign="top">To blury</td>', 'To blury', '2003-09-01 16:24:15.000000', NULL, 1),
