(406483, 35018, 9576, '<td valign="top">Wery good 10</td>', 'Wery good 10', '2003-09-01 16:50:29.000000', NULL, 1),
(406498, 35911, 6624, '<td valign="top">this is, for me, a lovely shot - I keep coming back to it and it could hang on my wall anytime. It''s very satisfying.</td>', 'this is, for me, a lovely shot - I keep coming back to it and it could hang on my wall anytime. It''s very satisfying.', '2003-09-01 17:22:25.000000', NULL, 1),
(406499, 35772, 6624, '<td valign="top">can''t argue whether this is repetition - precision repetition for sure.</td>', 'can''t argue whether this is repetition - precision repetition for sure.', '2003-09-01 17:23:02.000000', NULL, 1),
(406500, 35018, 6624, '<td valign="top">this is very nice. I like the warmth and glow as it climbs and the composition suits</td>', 'this is very nice. I like the warmth and glow as it climbs and the composition suits', '2003-09-01 17:24:11.000000', NULL, 1),
(406501, 35611, 6624, '<td valign="top">this is very nice, I can''t wait to find out where and what it is...the tones and textures are satisfying and the water landinds balance nicely</td>', 'this is very nice, I can''t wait to find out where and what it is...the tones and textures are satisfying and the water landinds balance nicely', '2003-09-01 17:25:24.000000', NULL, 1),
(406502, 35665, 6624, '<td valign="top">this is very nice, the repetition is there with motion and originality 8</td>', 'this is very nice, the repetition is there with motion and originality 8', '2003-09-01 17:25:43.000000', NULL, 1),
(406503, 35885, 6624, '<td valign="top">this is, of course, overwhelmingly repetitious..very nice echos of line and color</td>', 'this is, of course, overwhelmingly repetitious..very nice echos of line and color', '2003-09-01 17:26:41.000000', NULL, 1),
(406505, 35917, 6624, '<td valign="top">this has a very serene quality that is pleasant and successful overall</td>', 'this has a very serene quality that is pleasant and successful overall', '2003-09-01 17:27:34.000000', NULL, 1),
(406506, 35618, 6624, '<td valign="top">very original, very repetitious, nice technically</td>', 'very original, very repetitious, nice technically', '2003-09-01 17:28:13.000000', NULL, 1),
(406508, 35456, 6624, '<td valign="top">huge wedding I guess, very charming and very exacting response to challenge</td>', 'huge wedding I guess, very charming and very exacting response to challenge', '2003-09-01 17:28:50.000000', NULL, 1),
(406510, 35352, 6624, '<td valign="top">nice metronomic repetition, very original response</td>', 'nice metronomic repetition, very original response', '2003-09-01 17:29:29.000000', NULL, 1),
(406511, 35660, 6405, '<td valign="top">Nice done John !</td>', 'Nice done John !', '2003-09-01 17:29:38.000000', NULL, 1),
(406512, 35760, 6624, '<td valign="top">such a beautiful country - my two visits were such pleasure.  Could you think about cropping this to emphasize the blade of the windmills?</td>', 'such a beautiful country - my two visits were such pleasure.  Could you think about cropping this to emphasize the blade of the windmills?', '2003-09-01 17:31:04.000000', NULL, 1),
(406514, 34989, 6624, '<td valign="top">I love the textures in this, would you have thought of cropping the top so that only the pots make up the image?</td>', 'I love the textures in this, would you have thought of cropping the top so that only the pots make up the image?', '2003-09-01 17:32:18.000000', NULL, 1),
(406515, 35919, 6624, '<td valign="top">wonderful textures and contrasts</td>', 'wonderful textures and contrasts', '2003-09-01 17:32:46.000000', NULL, 1),
(406517, 35762, 6624, '<td valign="top">this has a great motion off to infinity (almost like a mirror where things goes on forever)  nice tones  would you have thought of a crop at the bottom to level the bridge out?</td>', 'this has a great motion off to infinity (almost like a mirror where things goes on forever)  nice tones  would you have thought of a crop at the bottom to level the bridge out?', '2003-09-01 17:35:10.000000', NULL, 1),
(406520, 35468, 6624, '<td valign="top">I love the movement in this - unfortunately I am distracted by the house on the left and the tree trunk on the right..the red is wonderful as well</td>', 'I love the movement in this - unfortunately I am distracted by the house on the left and the tree trunk on the right..the red is wonderful as well', '2003-09-01 17:37:04.000000', NULL, 1),
(406521, 35899, 6624, '<td valign="top">luscious ear of corn...nice response</td>', 'luscious ear of corn...nice response', '2003-09-01 17:37:49.000000', NULL, 1),
(406524, 35698, 6624, '<td valign="top">reconditioning the piano?  nice textures, tones, shapes - thy might possible have stood out even more with a crop at the top of the image</td>', 'reconditioning the piano?  nice textures, tones, shapes - thy might possible have stood out even more with a crop at the top of the image', '2003-09-01 17:39:42.000000', NULL, 1),
(406526, 35905, 6624, '<td valign="top">three generations and the genetic repetition is clear..very nice image and interesting response to the challenge</td>', 'three generations and the genetic repetition is clear..very nice image and interesting response to the challenge', '2003-09-01 17:41:04.000000', NULL, 1),
(406528, 34936, 6624, '<td valign="top">this has a wonderful feel - the rusty red barrier floats and the greens and the bit of brick picking it up again</td>', 'this has a wonderful feel - the rusty red barrier floats and the greens and the bit of brick picking it up again', '2003-09-01 17:42:16.000000', NULL, 1),
(406530, 35551, 6624, '<td valign="top">this is charming and I could only wish that the background had a brighter feel - not to compete with the colors but it detracts as it is</td>', 'this is charming and I could only wish that the background had a brighter feel - not to compete with the colors but it detracts as it is', '2003-09-01 17:43:14.000000', NULL, 1),
(406532, 34997, 6624, '<td valign="top">interesting response - great hummingbird</td>', 'interesting response - great hummingbird', '2003-09-01 17:44:11.000000', NULL, 1),
(406534, 35178, 6624, '<td valign="top">that''s scary...</td>', 'that''s scary...', '2003-09-01 17:45:40.000000', NULL, 1),
(406535, 35918, 6624, '<td valign="top">very funny</td>', 'very funny', '2003-09-01 17:47:26.000000', NULL, 1),
(406537, 35903, 3032, '<td valign="top">Great photo. The dark purple/grey atmosphere works so well here, I don''t know the right word for it, but it works so well with the crosses. Eyegrabbing compostition and aperture creativity makes me stop and look for a while, instead of just going on to the next photo.<br/>Excellent work.</td>', 'Great photo. The dark purple/grey atmosphere works so well here, I don''t know the right word for it, but it works so well with the crosses. Eyegrabbing compostition and aperture creativity makes me stop and look for a while, instead of just going on to the next photo.Excellent work.', '2003-09-01 17:53:07.000000', NULL, 1),
(406538, 35863, 6624, '<td valign="top">I struggled with this image, coming back to it several times...the angle in the upper right is jarring to me and at first I found it a distraction but I do keep coming back to it and I guess that my feeling is that it adds interest to an image filled with repetition in line, texture and shape</td>', 'I struggled with this image, coming back to it several times...the angle in the upper right is jarring to me and at first I found it a distraction but I do keep coming back to it and I guess that my feeling is that it adds interest to an image filled with repetition in line, texture and shape', '2003-09-01 17:56:30.000000', NULL, 1),
(406539, 35654, 6624, '<td valign="top">might have worked for back to school as well...very nice response</td>', 'might have worked for back to school as well...very nice response', '2003-09-01 17:57:34.000000', NULL, 1),
(406540, 35910, 3032, '<td valign="top">I would have cropped the bottom off.<br/>With the shadows, this makes an interesting pic.</td>', 'I would have cropped the bottom off.With the shadows, this makes an interesting pic.', '2003-09-01 17:57:43.000000', NULL, 1),
(406541, 35687, 6624, '<td valign="top">are those tomato leaves?</td>', 'are those tomato leaves?', '2003-09-01 17:58:51.000000', NULL, 1),
(406543, 35482, 6624, '<td valign="top">not only repetition but alliteration as well-</td>', 'not only repetition but alliteration as well-', '2003-09-01 18:00:17.000000', NULL, 1),
(406545, 35425, 6624, '<td valign="top">honeycomb?</td>', 'honeycomb?', '2003-09-01 18:01:38.000000', NULL, 1),
(406546, 35559, 6624, '<td valign="top">this has wonderful texture and light but it is drab overall -</td>', 'this has wonderful texture and light but it is drab overall -', '2003-09-01 18:03:01.000000', NULL, 1),
(406564, 35767, 280, '<td valign="top">The focus seems to be a little soft, also there is a orange tint to the picture, perhaps you could have converted it to B&amp;W?</td>', 'The focus seems to be a little soft, also there is a orange tint to the picture, perhaps you could have converted it to B&W?', '2003-09-01 18:31:33.000000', NULL, 1),
(406565, 35757, 280, '<td valign="top">Nice dof bot there seems to be a lack of contrast to give this image any real texture.</td>', 'Nice dof bot there seems to be a lack of contrast to give this image any real texture.', '2003-09-01 18:32:46.000000', NULL, 1),
(406603, 35741, 9232, '<td valign="top">Good perspective and I like the juxtaposition between the light and dark of the metalwork set against the rich reds and browns.  The lightness of the sky detracts from this shot just a little especially since the sky on the left is so hot with those clouds and the blue on the right shows a good tone that contributes to the contrasting colors and shades in the photo.  I wonder how this would look with a polarizing lens.  I''d also like to see this same shot not done for DPC where you remove the clouds from the top left and burn that side of the sky to match the righthand side.<br/> <br/>Good shot - 8</td>', 'Good perspective and I like the juxtaposition between the light and dark of the metalwork set against the rich reds and browns.  The lightness of the sky detracts from this shot just a little especially since the sky on the left is so hot with those clouds and the blue on the right shows a good tone that contributes to the contrasting colors and shades in the photo.  I wonder how this would look with a polarizing lens.  I''d also like to see this same shot not done for DPC where you remove the clouds from the top left and burn that side of the sky to match the righthand side. Good shot - 8', '2003-09-01 20:02:38.000000', NULL, 1),
(406605, 35661, 9232, '<td valign="top">Great choice of perspective.  I like the angle you picked and I like the contrasting interpretation between the exact repetition of the circular columns and the similar repetition of the leaves that differ from one column to the next. -  8</td>', 'Great choice of perspective.  I like the angle you picked and I like the contrasting interpretation between the exact repetition of the circular columns and the similar repetition of the leaves that differ from one column to the next. -  8', '2003-09-01 20:05:31.000000', NULL, 1),
(406606, 35851, 9232, '<td valign="top">You caught a great level of light on the chest and legs of the lighter colored horse.  I like the focus on the upper areas but perhaps a faster shutter speed would have stopped the legs in motion.  The hooves seem to blend into the ground. - 6</td>', 'You caught a great level of light on the chest and legs of the lighter colored horse.  I like the focus on the upper areas but perhaps a faster shutter speed would have stopped the legs in motion.  The hooves seem to blend into the ground. - 6', '2003-09-01 20:10:31.000000', NULL, 1),
(406610, 35938, 9232, '<td valign="top">Very active background and the tree trunks/limbs towards the top of the image break the cohesion of the greenery.  I''d prefer to see a smaller selection of this like the bottom lefthand corner - from the side to the center pole and only about half the image height.  That way you''d get good solid greenery.  Just my preference.</td>', 'Very active background and the tree trunks/limbs towards the top of the image break the cohesion of the greenery.  I''d prefer to see a smaller selection of this like the bottom lefthand corner - from the side to the center pole and only about half the image height.  That way you''d get good solid greenery.  Just my preference.', '2003-09-01 20:17:18.000000', NULL, 1),
(406612, 35745, 9232, '<td valign="top">Good subject.  The sky is too blown out.  I''d like to see the brightness and contrast adjusted to darken the sky a little.</td>', 'Good subject.  The sky is too blown out.  I''d like to see the brightness and contrast adjusted to darken the sky a little.', '2003-09-01 20:22:39.000000', NULL, 1),
(406613, 35640, 9232, '<td valign="top">Very busy composition.  Moving a little to the right and zooming in to capture the signs without the surrounding setting would help this image.</td>', 'Very busy composition.  Moving a little to the right and zooming in to capture the signs without the surrounding setting would help this image.', '2003-09-01 20:23:52.000000', NULL, 1),
(406616, 35935, 9232, '<td valign="top">Good subject and great use of lighting.  I''d be interested to hear about your lighting setup for this shot.  I like the comparison between the staright horizontal lines in the music (especially the notes) and the angles in the guitar.  You packed several layers of repetition into this image and captured it in a professional manner. - 10</td>', 'Good subject and great use of lighting.  I''d be interested to hear about your lighting setup for this shot.  I like the comparison between the staright horizontal lines in the music (especially the notes) and the angles in the guitar.  You packed several layers of repetition into this image and captured it in a professional manner. - 10', '2003-09-01 20:25:40.000000', NULL, 1),
(406620, 35675, 9232, '<td valign="top">Busy photo.  I''m sure the lighting is difficult with all the hot reflections off the chrome and reflactors.  You captured the reds and blues beautifully.<br/> <br/>I think lowering the camera angle and zomming in on one, two or three tires so that you saw the spokes of one wheel through the other would have been a picture more inviting to the viewer.  Likewise choosing a colored section of the bike might have produced less visual noise for the viewer.  Just my opinion.</td>', 'Busy photo.  I''m sure the lighting is difficult with all the hot reflections off the chrome and reflactors.  You captured the reds and blues beautifully. I think lowering the camera angle and zomming in on one, two or three tires so that you saw the spokes of one wheel through the other would have been a picture more inviting to the viewer.  Likewise choosing a colored section of the bike might have produced less visual noise for the viewer.  Just my opinion.', '2003-09-01 20:30:46.000000', NULL, 1),
(406622, 35368, 9232, '<td valign="top">Good capture but the colors seem to tend towards being too dark.  I''d be interested to see this same subject from a higher perspective (like if you climbed a ladder to put the roofs into the center of the composition).  A polarizing lens might have aided in the colors, too.</td>', 'Good capture but the colors seem to tend towards being too dark.  I''d be interested to see this same subject from a higher perspective (like if you climbed a ladder to put the roofs into the center of the composition).  A polarizing lens might have aided in the colors, too.', '2003-09-01 20:32:13.000000', NULL, 1),
(406625, 35851, 7969, '<td valign="top">I love the tones in this shot, I also like your choice of crop/compostion, great capture of movement too.  good work.</td>', 'I love the tones in this shot, I also like your choice of crop/compostion, great capture of movement too.  good work.', '2003-09-01 20:35:38.000000', NULL, 1),
(406626, 35772, 7969, '<td valign="top">Definately a good capture, i predict you will do very well in this challenge.  Good work.</td>', 'Definately a good capture, i predict you will do very well in this challenge.  Good work.', '2003-09-01 20:36:28.000000', NULL, 1),
(406627, 35813, 7969, '<td valign="top">I love this shot, the sharpnes, the color tones, the lighting, I think it is great can even see the ''grain'' of the stone. Well done.</td>', 'I love this shot, the sharpnes, the color tones, the lighting, I think it is great can even see the ''grain'' of the stone. Well done.', '2003-09-01 20:38:00.000000', NULL, 1),
(406629, 35653, 7969, '<td valign="top">Simple and elegant, tones and lighting and comp are pretty much perfect, a lovely abstract.</td>', 'Simple and elegant, tones and lighting and comp are pretty much perfect, a lovely abstract.', '2003-09-01 20:38:37.000000', NULL, 1),
(406635, 35769, 9232, '<td valign="top">Good color, lighting and cropping.  I''m interested to find out what edits you made in PS.</td>', 'Good color, lighting and cropping.  I''m interested to find out what edits you made in PS.', '2003-09-01 20:48:39.000000', NULL, 1),
(406640, 35910, 3102, '<td valign="top">I may have been tempted to leave out the brown tile at the bottom -- I think the yellow rivots stand out enough on their own.  I like the texture &amp; shadows on ''em!</td>', 'I may have been tempted to leave out the brown tile at the bottom -- I think the yellow rivots stand out enough on their own.  I like the texture & shadows on ''em!', '2003-09-01 21:00:24.000000', NULL, 1),
(406641, 35763, 3102, '<td valign="top">Beautiful!  I''ve been hoping to get a shot like this, but our weather has been so miserable this summer that any area balloon launches have been rained out.  Great colors!</td>', 'Beautiful!  I''ve been hoping to get a shot like this, but our weather has been so miserable this summer that any area balloon launches have been rained out.  Great colors!', '2003-09-01 21:01:43.000000', NULL, 1),
(406642, 35618, 3102, '<td valign="top">I was eyeing up a brush at our house as I was scrambling for an idea.  Now I''m glad I didn''t bother -- yours would have been much better!  :)  I like the way it turned out.  Without the title I may not have recognized it!</td>', 'I was eyeing up a brush at our house as I was scrambling for an idea.  Now I''m glad I didn''t bother -- yours would have been much better!  :)  I like the way it turned out.  Without the title I may not have recognized it!', '2003-09-01 21:03:06.000000', NULL, 1),
(406645, 35818, 2649, '<td valign="top">Nice photo.  The colors, focus, $ contrast are great.</td>', 'Nice photo.  The colors, focus, $ contrast are great.', '2003-09-01 21:10:03.000000', NULL, 1),
