(409130, 35463, 7304, '<td valign="top">Too much like an advertisement for Bulova Watches. Time is repetition but this watch is just sitting there right in the middle of the shot. Excellent sharpness. Advertisers would eat this up.</td>', 'Too much like an advertisement for Bulova Watches. Time is repetition but this watch is just sitting there right in the middle of the shot. Excellent sharpness. Advertisers would eat this up.', '2003-09-03 22:48:32.000000', NULL, 1),
(409134, 35761, 7304, '<td valign="top">Love the color. Sharp focus. Squares and circles. A lot going on in here.</td>', 'Love the color. Sharp focus. Squares and circles. A lot going on in here.', '2003-09-03 22:54:42.000000', NULL, 1),
