(409387, 35900, 10084, '<td valign="top">Great composition. Angle that you chose makes the shot very interesting. I like how the columns at the end seem to merge. You were able to capture some great shadows on the columns.</td>', 'Great composition. Angle that you chose makes the shot very interesting. I like how the columns at the end seem to merge. You were able to capture some great shadows on the columns.', '2003-09-04 03:06:07.000000', NULL, 1),
(409389, 35326, 10084, '<td valign="top">Very good imagination. I think the light is a bit harsh. Composition makes the piece a feast for the eyes. I could almost hear the music playing in the background. Great shot.</td>', 'Very good imagination. I think the light is a bit harsh. Composition makes the piece a feast for the eyes. I could almost hear the music playing in the background. Great shot.', '2003-09-04 03:08:00.000000', NULL, 1),
(409393, 35813, 10084, '<td valign="top">You were able to capture some really nice curves.  Your composition with the ground and the roof makes the piece very interesting. It leads your eyes around the columns. Great job.</td>', 'You were able to capture some really nice curves.  Your composition with the ground and the roof makes the piece very interesting. It leads your eyes around the columns. Great job.', '2003-09-04 03:10:01.000000', NULL, 1),
(409396, 35780, 10084, '<td valign="top">Composition is good. The lighting and the darkness of the holes are very interesting. The color is really nice. The reflections are beautiful.</td>', 'Composition is good. The lighting and the darkness of the holes are very interesting. The color is really nice. The reflections are beautiful.', '2003-09-04 03:12:10.000000', NULL, 1),
(409399, 35911, 10084, '<td valign="top">This piece is very interesting.  The columns in the pier leads your eyes straight back and you get a nice wave coming in. It''s like a feast for the eyes. The blues in the sky also help . Some beautiful shadows and reflections on the pier columns. <br/> <br/>Excellent picture.</td>', 'This piece is very interesting.  The columns in the pier leads your eyes straight back and you get a nice wave coming in. It''s like a feast for the eyes. The blues in the sky also help . Some beautiful shadows and reflections on the pier columns.  Excellent picture.', '2003-09-04 03:14:21.000000', NULL, 1),
(409402, 34997, 10084, '<td valign="top">Very clear picture of the hummingbird body and the wings flapping leads to a great shot.</td>', 'Very clear picture of the hummingbird body and the wings flapping leads to a great shot.', '2003-09-04 03:15:40.000000', NULL, 1),
