(410293, 35530, 811, '<td valign="top">The lighting is interesting, though it sets up a bit more contrast than I personally like or think is effective.  The biggest "gripe" (mind you it is only my opinion) is that the picture seems off kilter to me.  Maybe it needs to be rotated a touch clockwise to even it, or ccw to make it obviously off line.</td>', 'The lighting is interesting, though it sets up a bit more contrast than I personally like or think is effective.  The biggest "gripe" (mind you it is only my opinion) is that the picture seems off kilter to me.  Maybe it needs to be rotated a touch clockwise to even it, or ccw to make it obviously off line.', '2003-09-05 01:46:38.000000', NULL, 1),
(410297, 35320, 811, '<td valign="top">I love the sharpness of the colors and the contrast of the prism with the solid black background.</td>', 'I love the sharpness of the colors and the contrast of the prism with the solid black background.', '2003-09-05 01:50:20.000000', NULL, 1),
(410298, 35797, 811, '<td valign="top">great quality and I like your choice of bw</td>', 'great quality and I like your choice of bw', '2003-09-05 01:51:13.000000', NULL, 1),
(410330, 35780, 811, '<td valign="top">Great choice for this challenge.  The light almost washes out the center of the picture, but it is still nicely done.</td>', 'Great choice for this challenge.  The light almost washes out the center of the picture, but it is still nicely done.', '2003-09-05 02:23:30.000000', NULL, 1),
(410333, 35935, 811, '<td valign="top">I really like the dramatic contrast between the dark and light areas.  Excellent subject choice, and very well done.</td>', 'I really like the dramatic contrast between the dark and light areas.  Excellent subject choice, and very well done.', '2003-09-05 02:25:05.000000', NULL, 1),
(410342, 35927, 811, '<td valign="top">This has a cool effect -- it is like they are rising and going to the right.</td>', 'This has a cool effect -- it is like they are rising and going to the right.', '2003-09-05 02:32:00.000000', NULL, 1),
(410353, 35911, 811, '<td valign="top">Great shot.  Cropping or framing it so that the first two pillars on the left and right weren''t showing might have been effective as well.</td>', 'Great shot.  Cropping or framing it so that the first two pillars on the left and right weren''t showing might have been effective as well.', '2003-09-05 02:47:19.000000', NULL, 1),
