(410444, 35892, 472, '<td valign="top">cool shot. i wish the front most dancer was sharp, though.  i also see alot more repetition strength at the leg level.  cropping this just below the bust might strengthen the shot for dpc.</td>', 'cool shot. i wish the front most dancer was sharp, though.  i also see alot more repetition strength at the leg level.  cropping this just below the bust might strengthen the shot for dpc.', '2003-09-05 08:27:59.000000', NULL, 1),
(410450, 35932, 9232, '<td valign="top">Creative interpretation.  I like the focus being away from the camera so that the nearest objects are thrown OOF.  I''d be interested to see what it looks like if you focus on the center mass of objects rather than the fartherest grouping.  Lighting choice is superb although a bit heavy; might want to diffuse that light a little more.  Overall this met the challenge, showed creativity and was a technically superior job.  The lighting cost the 1 point. - 9</td>', 'Creative interpretation.  I like the focus being away from the camera so that the nearest objects are thrown OOF.  I''d be interested to see what it looks like if you focus on the center mass of objects rather than the fartherest grouping.  Lighting choice is superb although a bit heavy; might want to diffuse that light a little more.  Overall this met the challenge, showed creativity and was a technically superior job.  The lighting cost the 1 point. - 9', '2003-09-05 08:39:56.000000', NULL, 1),
(410480, 35769, 10768, '<td valign="top">Beautiful colors.</td>', 'Beautiful colors.', '2003-09-05 10:26:48.000000', NULL, 1),
