(410684, 35356, 2612, '<td valign="top">Good composition, but I think you need to go for maximum depth of field to make this work really good. Small aperture may require tripod, but it would help this move from good to very interesting.</td>', 'Good composition, but I think you need to go for maximum depth of field to make this work really good. Small aperture may require tripod, but it would help this move from good to very interesting.', '2003-09-05 17:28:30.000000', NULL, 1),
(410687, 35316, 2612, '<td valign="top">Good texture and nice repetition. Needs something to punch it up a bit, but I cannot think of a specific recommendation.</td>', 'Good texture and nice repetition. Needs something to punch it up a bit, but I cannot think of a specific recommendation.', '2003-09-05 17:31:34.000000', NULL, 1),
(410690, 35695, 2612, '<td valign="top">You got the repetition and the composition flows off to the left nicely. I think you need to wait for some more interesting lighting to pick this up a little.The bright spot on the left pulls away from the arches, but just a little.</td>', 'You got the repetition and the composition flows off to the left nicely. I think you need to wait for some more interesting lighting to pick this up a little.The bright spot on the left pulls away from the arches, but just a little.', '2003-09-05 17:34:34.000000', NULL, 1),
