(411250, 35938, 10402, '<td valign="top">There is certainly repetition, and the boards are interestingly different from each other, but the focused background is even more interesting and steals the viewers attention away. A shallow depth of field to knock the background out of focus would have helped prevent this.</td>', 'There is certainly repetition, and the boards are interestingly different from each other, but the focused background is even more interesting and steals the viewers attention away. A shallow depth of field to knock the background out of focus would have helped prevent this.', '2003-09-06 21:55:19.000000', NULL, 1),
(411260, 35780, 11899, '<td valign="top">I wish I knew what this was a picture of...focus isn''t even, uneven glare too.</td>', 'I wish I knew what this was a picture of...focus isn''t even, uneven glare too.', '2003-09-06 22:47:35.000000', NULL, 1),
