(411278, 35935, 11899, '<td valign="top">I like this one..one of my favorites in the category..I wish there was some lighting and contrast on the guitar surface though</td>', 'I like this one..one of my favorites in the category..I wish there was some lighting and contrast on the guitar surface though', '2003-09-06 23:11:20.000000', NULL, 1),
(411279, 35917, 11899, '<td valign="top">Very pretty shot</td>', 'Very pretty shot', '2003-09-06 23:11:52.000000', NULL, 1),
