(411284, 35636, 11899, '<td valign="top">Cool idea..and the sepia(?) is a nice touch</td>', 'Cool idea..and the sepia(?) is a nice touch', '2003-09-06 23:16:26.000000', NULL, 1),
(411285, 35932, 3540, '<td valign="top">It walks down stairs, alone or in pairs......  Good concept for a photo.  I think this one should do well.   Everyone knows its Slinky.  Its fun for a girl and a boy.</td>', 'It walks down stairs, alone or in pairs......  Good concept for a photo.  I think this one should do well.   Everyone knows its Slinky.  Its fun for a girl and a boy.', '2003-09-06 23:17:33.000000', NULL, 1),
(411286, 35018, 3540, '<td valign="top">This one should be in the ribbons.  Great abstract of this tower.  The pattern is outstanding. 10</td>', 'This one should be in the ribbons.  Great abstract of this tower.  The pattern is outstanding. 10', '2003-09-06 23:18:18.000000', NULL, 1),
(411287, 35859, 11899, '<td valign="top">Interesting...I wish either the foremost symbols were the sharpest or else a row further in were.</td>', 'Interesting...I wish either the foremost symbols were the sharpest or else a row further in were.', '2003-09-06 23:19:44.000000', NULL, 1),
(411288, 35320, 3540, '<td valign="top">Awesome clear photo.  Very interesting colors.  I don''t see it fitting in this challenge well.  The colors are interesting, but the subject really doesn''t do it for me.  Very very well taken.</td>', 'Awesome clear photo.  Very interesting colors.  I don''t see it fitting in this challenge well.  The colors are interesting, but the subject really doesn''t do it for me.  Very very well taken.', '2003-09-06 23:19:55.000000', NULL, 1),
