(411318, 35507, 6870, '<td valign="top">Nice tones. Maybe push your whites  just a bit more, but very, very nice. 9</td>', 'Nice tones. Maybe push your whites  just a bit more, but very, very nice. 9', '2003-09-07 00:12:59.000000', NULL, 1),
