(411334, 35797, 6870, '<td valign="top">I love the harsh shadows in this image. Unusual and distinctive. your lighting gives these dummies a sinister feel. 9</td>', 'I love the harsh shadows in this image. Unusual and distinctive. your lighting gives these dummies a sinister feel. 9', '2003-09-07 00:30:17.000000', NULL, 1),
(411335, 35905, 6870, '<td valign="top">Super idea. I love the little boy''s expression and elbow thing. The guy in the middle is kind of ugly, though. I''m sure his brother is much better looking. Does he have one? 8</td>', 'Super idea. I love the little boy''s expression and elbow thing. The guy in the middle is kind of ugly, though. I''m sure his brother is much better looking. Does he have one? 8', '2003-09-07 00:31:48.000000', NULL, 1),
(411338, 35947, 6870, '<td valign="top">Nice colors and point of view. The lines you create here really pull us in. Image seems a bit blurry, though.</td>', 'Nice colors and point of view. The lines you create here really pull us in. Image seems a bit blurry, though.', '2003-09-07 00:32:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(411339, 35948, 6870, '<td valign="top">I can see the repetition here. It might be clearer if you focused on the shadow more or perhaps found a point of view that allowed us to see more light in the  holes. Nice idea and nice tones. B/W a good choice.</td>', 'I can see the repetition here. It might be clearer if you focused on the shadow more or perhaps found a point of view that allowed us to see more light in the  holes. Nice idea and nice tones. B/W a good choice.', '2003-09-07 00:34:10.000000', NULL, 1),
(411340, 35326, 6870, '<td valign="top">Really cool idea! I like the implied line you''ve created with your point of view. Colors and nice and rich, too. It''s a bit out of focus, though.</td>', 'Really cool idea! I like the implied line you''ve created with your point of view. Colors and nice and rich, too. It''s a bit out of focus, though.', '2003-09-07 00:35:04.000000', NULL, 1),
(411359, 35349, 6325, '<td valign="top">I like the soft focus and the splashes of color.</td>', 'I like the soft focus and the splashes of color.', '2003-09-07 01:16:25.000000', NULL, 1),
(411364, 35899, 6325, '<td valign="top">I can just taste the corn. Excellent colors.</td>', 'I can just taste the corn. Excellent colors.', '2003-09-07 01:23:11.000000', NULL, 1),
(411382, 35919, 10263, '<td valign="top">No idea what this is but I like the colors and the texture.  Shoe laces?</td>', 'No idea what this is but I like the colors and the texture.  Shoe laces?', '2003-09-07 03:16:20.000000', NULL, 1),
(411383, 35951, 10263, '<td valign="top">Nice colors. It doesn''t keep my interest long.</td>', 'Nice colors. It doesn''t keep my interest long.', '2003-09-07 03:17:49.000000', NULL, 1),
(411384, 35249, 1031, '<td valign="top">I would have cropped a tiny bit off the left. Otherwise good idea, well-done.</td>', 'I would have cropped a tiny bit off the left. Otherwise good idea, well-done.', '2003-09-07 03:21:14.000000', NULL, 1),
(411385, 35772, 1031, '<td valign="top">If only the nearest plane hadn''t been a teensy bit late making the maneuver you''d have gotten a tiny bit of sky at the top. Excellent action shot.</td>', 'If only the nearest plane hadn''t been a teensy bit late making the maneuver you''d have gotten a tiny bit of sky at the top. Excellent action shot.', '2003-09-07 03:24:22.000000', NULL, 1),
(411386, 35523, 1031, '<td valign="top">Oooh, I almost used a variation of this shot; not a close-up though. Here the bright lines form an additional repetitive element to the escalator steps themselves.</td>', 'Oooh, I almost used a variation of this shot; not a close-up though. Here the bright lines form an additional repetitive element to the escalator steps themselves.', '2003-09-07 03:36:35.000000', NULL, 1),
(411387, 35715, 1031, '<td valign="top">I like the idea and composition but would try other color schemes; it seems too flat to be exciting. Doesn''t mean this mightn''t be the best in the long run though ....</td>', 'I like the idea and composition but would try other color schemes; it seems too flat to be exciting. Doesn''t mean this mightn''t be the best in the long run though ....', '2003-09-07 03:41:44.000000', NULL, 1),
(411388, 35753, 1031, '<td valign="top">I tried to set up a shot like this once, and it was a pain -- you did a nice job with the "framing."</td>', 'I tried to set up a shot like this once, and it was a pain -- you did a nice job with the "framing."', '2003-09-07 03:43:43.000000', NULL, 1),
(411395, 35532, 4767, '<td valign="top">If you shoot it, votes will come...</td>', 'If you shoot it, votes will come...', '2003-09-07 05:40:13.000000', NULL, 1),
(411396, 35463, 4767, '<td valign="top">Afraid I don''t understand this.  Where is the repetition?  Nice photo but...  is this on theme?</td>', 'Afraid I don''t understand this.  Where is the repetition?  Nice photo but...  is this on theme?', '2003-09-07 05:44:46.000000', NULL, 1),
(411397, 35775, 4767, '<td valign="top">WOW! - 10-</td>', 'WOW! - 10-', '2003-09-07 05:45:37.000000', NULL, 1),
(411416, 35663, 2716, '<td valign="top">You lucky bugger I can never even catch one.  Now you caught tow.  lol.  Fits the challenge nicely.  Good job.  Jacko.  9</td>', 'You lucky bugger I can never even catch one.  Now you caught tow.  lol.  Fits the challenge nicely.  Good job.  Jacko.  9', '2003-09-07 08:57:58.000000', NULL, 1),
(411420, 35641, 3540, '<td valign="top">I wouldn''t have made the perspective from this odd angle.  I''d have done it straight, or went right for the corner to corner.  To each his own though.   The colors are pretty bland.  I bet a sunnier day would''ve helped you out.  Not bad, but it needs something.</td>', 'I wouldn''t have made the perspective from this odd angle.  I''d have done it straight, or went right for the corner to corner.  To each his own though.   The colors are pretty bland.  I bet a sunnier day would''ve helped you out.  Not bad, but it needs something.', '2003-09-07 09:12:18.000000', NULL, 1),
(411421, 35772, 3540, '<td valign="top">Awesome capture.  Good framing.... looks like they didn''t make it easy for you.  Nice work.</td>', 'Awesome capture.  Good framing.... looks like they didn''t make it easy for you.  Nice work.', '2003-09-07 09:13:05.000000', NULL, 1),
(411422, 35356, 3540, '<td valign="top">This needs ot have someplace be the focus.  The whole thing looks a bit blurry to me.  Good idea, the execution just isn''t quite there.</td>', 'This needs ot have someplace be the focus.  The whole thing looks a bit blurry to me.  Good idea, the execution just isn''t quite there.', '2003-09-07 09:16:10.000000', NULL, 1),
(411423, 35857, 3540, '<td valign="top">I think you could have went with any of these elements as a subject.  I''m not sure I like this with all of that present.  I think I''d have chosen the floor and went with that.  This is a nice pic, don''t get me wrong.</td>', 'I think you could have went with any of these elements as a subject.  I''m not sure I like this with all of that present.  I think I''d have chosen the floor and went with that.  This is a nice pic, don''t get me wrong.', '2003-09-07 09:20:48.000000', NULL, 1),
(411424, 35152, 3540, '<td valign="top">Field of Focus is tiny and not located in the right spot.  I think a successful photo shot like this will have the focus nearest the viewer., or at least as near as possible.</td>', 'Field of Focus is tiny and not located in the right spot.  I think a successful photo shot like this will have the focus nearest the viewer., or at least as near as possible.', '2003-09-07 09:21:54.000000', NULL, 1),
(411425, 35618, 3540, '<td valign="top">Very creative.  Nice sharp focus and a good crisp picture.</td>', 'Very creative.  Nice sharp focus and a good crisp picture.', '2003-09-07 09:23:23.000000', NULL, 1),
(411428, 35655, 3540, '<td valign="top">The light and the dark on this one aren''t helping it.  I''d like to see it all in the light.  Interesting way to build a building.  Its a worthy subject, just not at this time of day.</td>', 'The light and the dark on this one aren''t helping it.  I''d like to see it all in the light.  Interesting way to build a building.  Its a worthy subject, just not at this time of day.', '2003-09-07 09:31:52.000000', NULL, 1),
(411429, 35936, 3540, '<td valign="top">I would have greyscaled this one.  I think the effect of greyscaling this would make the mood a bit darker and enhance the overall mood of the photo.</td>', 'I would have greyscaled this one.  I think the effect of greyscaling this would make the mood a bit darker and enhance the overall mood of the photo.', '2003-09-07 09:34:24.000000', NULL, 1),
(411430, 35741, 3540, '<td valign="top">NIce pic.  GOod work.  Reminds me Xertions pic for the symmetry challenege</td>', 'NIce pic.  GOod work.  Reminds me Xertions pic for the symmetry challenege', '2003-09-07 09:35:03.000000', NULL, 1),
(411432, 35388, 3540, '<td valign="top">Hmmmmm, I think you should reconsider what you enter.  This is so blurry and shows the photographer that no matter what the subject matter, you''re going to get a slew of ones and twos.  That could be construed as repetition though.</td>', 'Hmmmmm, I think you should reconsider what you enter.  This is so blurry and shows the photographer that no matter what the subject matter, you''re going to get a slew of ones and twos.  That could be construed as repetition though.', '2003-09-07 09:37:55.000000', NULL, 1),
(411445, 35763, 4090, '<td valign="top">10/10 Good luck -- hope to see this with a ribbon tomorrow.</td>', '10/10 Good luck -- hope to see this with a ribbon tomorrow.', '2003-09-07 10:19:41.000000', NULL, 1),
(411447, 35611, 10402, '<td valign="top">You''ve used just the right shutter speed to get some motion blur in the waterfalls yet freeze capture the texture of the water surface. But the strong lines in the image lead the viewer''s eye out of the photo, leaving him unsatisfied, wondering what''s just beyond the border.</td>', 'You''ve used just the right shutter speed to get some motion blur in the waterfalls yet freeze capture the texture of the water surface. But the strong lines in the image lead the viewer''s eye out of the photo, leaving him unsatisfied, wondering what''s just beyond the border.', '2003-09-07 10:33:29.000000', NULL, 1),
(411451, 35932, 10402, '<td valign="top">Great concept and interesting image. The lighting is good and focusing on the far side was a good choice. Some minor imperfections: noise to the left of center and aliasing on some of the coils, a couple of bright spots, and the table edge is somewhat distracting. But overall well done.</td>', 'Great concept and interesting image. The lighting is good and focusing on the far side was a good choice. Some minor imperfections: noise to the left of center and aliasing on some of the coils, a couple of bright spots, and the table edge is somewhat distracting. But overall well done.', '2003-09-07 10:47:20.000000', NULL, 1),
(411482, 35936, 10414, '<td valign="top">Great shot!  Where was this taken??  :)</td>', 'Great shot!  Where was this taken??  :)', '2003-09-07 12:39:38.000000', NULL, 1),
(411485, 35784, 10414, '<td valign="top">A beautiful, creative, perfect picture!!  ! This SHOULD be in the top 3 IMO!!! :)  10</td>', 'A beautiful, creative, perfect picture!!  ! This SHOULD be in the top 3 IMO!!! :)  10', '2003-09-07 12:48:35.000000', NULL, 1),
(411500, 35418, 11034, '<td valign="top">number one is the repetition element? Nice shoot but too small. Good luck.</td>', 'number one is the repetition element? Nice shoot but too small. Good luck.', '2003-09-07 13:56:17.000000', NULL, 1),
(411505, 35857, 7778, '<td valign="top">The strength of this wonderful image, IMO, lies in the fact that its latent or emotive subject seems entirely open to personal interpretation. Despite the extremes of lighting and a consequential elimination of detail over large parts of the image (the dark facades on both sides of passage, the bright day-lit arched patio at the focus of perspective), the capture remains coherently clear and satisfying. The lone figure caught in mid-step on this sea of diamonds (tile floor) only emphasizes an apparent and almost emotinal emptiness, which aptly balances a potentially busy shot. The dynamic perspective maps the picture perfectly, cutting a distinct path for the eye.<br/> <br/>Personally, this is an image which appeals to my tastes in no small way, either.</td>', 'The strength of this wonderful image, IMO, lies in the fact that its latent or emotive subject seems entirely open to personal interpretation. Despite the extremes of lighting and a consequential elimination of detail over large parts of the image (the dark facades on both sides of passage, the bright day-lit arched patio at the focus of perspective), the capture remains coherently clear and satisfying. The lone figure caught in mid-step on this sea of diamonds (tile floor) only emphasizes an apparent and almost emotinal emptiness, which aptly balances a potentially busy shot. The dynamic perspective maps the picture perfectly, cutting a distinct path for the eye. Personally, this is an image which appeals to my tastes in no small way, either.', '2003-09-07 14:45:48.000000', NULL, 1),
