(411711, 35536, 8522, '<td valign="top">Too symmetrical for me. The ratio of sky to ground seems very odd. 5</td>', 'Too symmetrical for me. The ratio of sky to ground seems very odd. 5', '2003-09-07 20:30:01.000000', NULL, 1),
(411712, 35663, 8522, '<td valign="top">Oh wow! great colours, good dof. Not entirely convinced by the composition, but it''s a great capture. 9</td>', 'Oh wow! great colours, good dof. Not entirely convinced by the composition, but it''s a great capture. 9', '2003-09-07 20:31:04.000000', NULL, 1),
