(411927, 35905, 10402, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by dsidwell:</b></div><hr/><i>Super idea. I love the little boy''s expression and elbow thing. The guy in the middle is kind of ugly, though. I''m sure his brother is much better looking. Does he have one? 8</i></td></tr></table> <br/> <br/>Indeed the guy in the middle does have a brother! <a href="//dpchallenge.com/image.php?IMAGE_ID=35006" rel="nofollow" target="_blank">//dpchallenge.com/image.php?IMAGE_ID=35006</a></td>', 'Originally posted by dsidwell:Super idea. I love the little boy''s expression and elbow thing. The guy in the middle is kind of ugly, though. I''m sure his brother is much better looking. Does he have one? 8  Indeed the guy in the middle does have a brother! //dpchallenge.com/image.php?IMAGE_ID=35006', '2003-09-08 01:27:00.000000', NULL, 0),
(411928, 35772, 10263, '<td valign="top">Congrats on a well deserved ribbon. Love the shot :)</td>', 'Congrats on a well deserved ribbon. Love the shot :)', '2003-09-08 01:28:30.000000', NULL, 0),
(411939, 35911, 10263, '<td valign="top">Congratulations on the ribbon. Beautiful photo :)</td>', 'Congratulations on the ribbon. Beautiful photo :)', '2003-09-08 01:31:09.000000', NULL, 0),
(411940, 35696, 2333, '<td valign="top">Hah!<br/>You had me fooled... I thought this was an antenna. Sure looks like one! Great shot.</td>', 'Hah!You had me fooled... I thought this was an antenna. Sure looks like one! Great shot.', '2003-09-08 01:32:02.000000', NULL, 0),
