(411988, 35763, 7778, '<td valign="top"><b>Zeus'' Top Pic(k)s: 3. Place</b></td>', 'Zeus'' Top Pic(k)s: 3. Place', '2003-09-08 02:00:16.000000', NULL, 0),
(411990, 35740, 11457, '<td valign="top">Thanks to everybody who posted their comments and advice! I do agree that I should have focused more carefully on the first row of beads. Also, more DoF would have probably helped, although I felt that separating the first row of beads from the others was somehow important. I used such a shallow DoF because I was holding the plastic tube with my hands (you can see my fingers on the tube, if you watch carefully) during the 1-sec exposure. A smaller aperture would have required a longer exposure time, and motion blur would become visible in the reflections. Next time I''ll try to secure things in place, somehow. :)<br/><br/><i>Message edited by author 2003-09-08 01:12:21.</i></td>', 'Thanks to everybody who posted their comments and advice! I do agree that I should have focused more carefully on the first row of beads. Also, more DoF would have probably helped, although I felt that separating the first row of beads from the others was somehow important. I used such a shallow DoF because I was holding the plastic tube with my hands (you can see my fingers on the tube, if you watch carefully) during the 1-sec exposure. A smaller aperture would have required a longer exposure time, and motion blur would become visible in the reflections. Next time I''ll try to secure things in place, somehow. :)', '2003-09-08 02:03:16.000000', '2003-09-08 02:12:21.000000', 0),
(412006, 35772, 10170, '<td valign="top">Absolutely awesome shot, the timing is perfect!<br/> <br/>Says an awful lot about the flyers too, look how perfectly they are in position even following a look like that.<br/> <br/>Excellent!</td>', 'Absolutely awesome shot, the timing is perfect! Says an awful lot about the flyers too, look how perfectly they are in position even following a look like that. Excellent!', '2003-09-08 02:11:57.000000', NULL, 0),
(412008, 35911, 10170, '<td valign="top">Excellent shot, great time of day to get that lighting just right as well :)</td>', 'Excellent shot, great time of day to get that lighting just right as well :)', '2003-09-08 02:14:00.000000', NULL, 0),
(412011, 35018, 3554, '<td valign="top">Congrats on the ribbon...met the challenge wonderfully.</td>', 'Congrats on the ribbon...met the challenge wonderfully.', '2003-09-08 02:15:51.000000', NULL, 0),
(412014, 35456, 3554, '<td valign="top">Ah so close!  :)<br/> <br/>4th is a bittersweet place, congratulations though.</td>', 'Ah so close!  :) 4th is a bittersweet place, congratulations though.', '2003-09-08 02:19:36.000000', NULL, 0),
(412024, 35660, 3554, '<td valign="top">I''d given this a nine and expected it to place a fair bit higher. I''m surprised how poorly shots that implied real life repetition scored. <br/> <br/>Good work and met the challenge well.</td>', 'I''d given this a nine and expected it to place a fair bit higher. I''m surprised how poorly shots that implied real life repetition scored.  Good work and met the challenge well.', '2003-09-08 02:26:45.000000', NULL, 0),
